1	import { Fragment, useState, type ReactNode } from "react";
2	import { Link } from "react-router-dom";
3	import { AnimIcon, type IconName } from "@/components/art";
4	import { ErrorBoundary } from "@/components/ErrorBoundary";
5	import { Logo, LogoImage, type ImageName } from "@/components/Logo";
6	import AIReasoning from "@/components/smoothui/ai-reasoning";
7	import { LiveTiles } from "@/components/LiveTiles";
8	import { NumberTicker } from "@/components/NumberTicker";
9	import { RepoChat } from "@/components/RepoChat";
10	import { SolutionTabs } from "@/components/SolutionTabs";
11	import { Story, StorySkeleton } from "@/components/Story";
12	import { Terminal, type TermRow } from "@/components/Terminal";
13	import { AgentOrb, Eyebrow, Mark, Reveal, StatusBadge } from "@/components/ui-bits";
14	import type { RunDetail, RunSummary, Step } from "@/lib/api";
15	import { fixLabel, fmtDur, isShowable, parsePatch, STATUS_ORDER, statusMeta, stepOk } from "@/lib/run";
16	import { cn, INSTALL_URL } from "@/lib/utils";
17	import { useLandingData, type LandingData, type StatGroup } from "./landing-data";
18	
19	const LABEL = "font-mono text-xs uppercase tracking-[0.12em] text-muted-foreground";
20	
21	/** The command that reproduces the featured run, as logged in the build log. */
22	const commandFor = (r: { repo?: string | null; sha?: string | null; path?: string | null } | null) =>
23	  r?.repo && r.sha ? `uv run python -m resurgo.run ${r.repo} ${r.sha}${r.path ? ` --path ${r.path}` : ""}` : null;
24	
25	const stepRows = (steps: Step[], prefix: string): TermRow[] =>
26	  steps.map((s, i) => ({
27	    id: `${prefix}${i}`,
28	    kind: "step",
29	    label: s.name,
30	    command: s.command,
31	    ok: stepOk(s),
32	    duration: s.duration_s,
33	    lines: s.output_tail,
34	  }));
35	
36	function CommandChip({ command }: { command: string }) {
37	  const [copied, setCopied] = useState(false);
38	  return (
39	    <div className="flex max-w-full items-center gap-2 rounded-lg border border-border bg-terminal py-1.5 pl-4 pr-1.5 font-mono text-sm text-terminal-ink">
40	      <span aria-hidden className="text-muted-foreground">$</span>
41	      <code title={command} className="min-w-0 flex-1 truncate py-1">{command}</code>
42	      <button
43	        type="button"
44	        onClick={() => {
45	          navigator.clipboard?.writeText(command).then(() => {
46	            setCopied(true);
47	            setTimeout(() => setCopied(false), 1800);
48	          }).catch(() => undefined);
49	        }}
50	        className="press shrink-0 rounded-md border border-control px-3 py-1.5 text-xs font-semibold hover:bg-muted pointer-coarse:min-h-11 pointer-coarse:px-4"
51	      >
52	        <span aria-live="polite">
53	          <span key={String(copied)} className="settle inline-block">{copied ? "✓ Copied" : "Copy"}</span>
54	        </span>
55	      </button>
56	    </div>
57	  );
58	}
59	
60	/* 1. Hero ------------------------------------------------------------------ */
61	function Hero({ data }: { data: LandingData }) {
62	  const f = data.featured;
63	  // From the list row, so the command is there as soon as the list is, and the hero does not grow when the record arrives.
64	  const cmd = commandFor(f?.result ?? data.featuredSummary);
65	  return (
66	    <section className="mx-auto grid w-full max-w-7xl gap-14 px-4 pb-24 pt-16 sm:px-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.05fr)] lg:pt-24">
67	      <div className="min-w-0">
68	        <Eyebrow>An agent that keeps projects runnable</Eyebrow>
69	        <h1 className="text-[clamp(3rem,7vw,5.75rem)] font-semibold leading-[0.95] tracking-[-0.03em]">
70	          Your projects, <Mark>runnable</Mark> again.
71	        </h1>
72	        <p className="mt-7 max-w-xl text-xl leading-relaxed text-muted-foreground">
73	          Resurgo fresh-clones your repos, repairs what rotted, and proves each fix in a clean container before it opens a pull request.
74	        </p>
75	        <div className="mt-9 flex flex-wrap items-center gap-3">
76	          <a
77	            href={INSTALL_URL}
78	            className="press inline-flex min-h-12 items-center gap-2.5 rounded-lg border border-accent-strong bg-accent-strong px-6 text-base font-semibold text-on-accent hover:opacity-90"
79	          >
80	            <Logo name="github" size="1.25em" decorative />
81	            Install on GitHub
82	          </a>
83	          <Link
84	            to="/runs"
85	            className="press inline-flex min-h-12 items-center rounded-lg border border-control px-5 text-base font-semibold hover:bg-muted"
86	          >
87	            See real runs
88	          </Link>
89	        </div>
90	        <p className="mt-4 max-w-xl text-sm text-muted-foreground">
91	          Public repos only · Pull requests only for fixes that pass a clean container ·{" "}
92	          <Link to="/data" className="underline underline-offset-4 hover:text-foreground">What Resurgo stores</Link>
93	        </p>
94	        {cmd && (
95	          <div className="mt-8 max-w-xl">
96	            <p className="mb-2 text-sm text-muted-foreground">or run it yourself:</p>
97	            <CommandChip command={cmd} />
98	            <p className="mt-2 text-sm">
99	              <a
100	                href="https://github.com/Timidan/resurgo#run-it-yourself"
101	                className="text-muted-foreground underline underline-offset-4 hover:text-foreground"
102	              >
103	                What you need to run it
104	              </a>
105	            </p>
106	          </div>
107	        )}
108	        <section className="mt-12" aria-label="Built with">
109	          <p className={LABEL}>Built with</p>
110	          <ul className="mt-4 flex flex-wrap items-start gap-x-10 gap-y-6" role="list">
111	            <li className="flex flex-col gap-2">
112	              <span className="flex items-center gap-3">
113	                <LogoImage name="neatlogsIcon" size="40px" className="rounded-lg" />
114	                <Logo name="neatlogs" brand size="26px" className="text-foreground" />
115	              </span>
116	              <span className="text-xs text-muted-foreground">traces every run</span>
117	            </li>
118	            <li className="flex flex-col gap-2">
119	              <Logo name="entire" brand size="32px" />
120	              <span className="text-xs text-muted-foreground">checkpoints every commit</span>
121	            </li>
122	          </ul>
123	        </section>
124	      </div>
125	
126	      <div className="min-w-0 lg:pt-4">
127	        {f ? (
128	          <Story detail={f} replayOnHover label={`A real run of ${f.result.repo}, replayed`} />
129	        ) : data.loading || data.featuredSummary ? (
130	          <StorySkeleton tiles={data.featuredSummary?.verifier_steps?.length} />
131	        ) : null}
132	      </div>
133	    </section>
134	  );
135	}
136	
137	/* 3. Three steps, as story rows -------------------------------------------- */
138	function Steps({ data }: { data: LandingData }) {
139	  const f = data.featured;
140	  if (!f) return null;
141	  const a = f.result.agent;
142	  const clone = (a?.steps ?? []).filter((s) => s.name === "clone" || s.name === "detect").slice(0, 2);
143	  const attempts = a?.attempts ?? [];
144	  const proof = f.result.verifier?.steps ?? [];
145	  const items: { icon: IconName; title: string; body: string; rows: TermRow[] }[] = [
146	    {
147	      icon: "check" as const,
148	      title: "A fresh clone, every time",
149	      body: "No cached node_modules, no warm machine. If it only works on your laptop, this is where it stops working.",
150	      rows: stepRows(clone, "c"),
151	    },
152	    {
153	      icon: "repair" as const,
154	      title: "The least invasive fix first",
155	      body: "Version pins and config before anything else. Source code is only ever proposed, and waits for your approval.",
156	      rows: attempts.map((x, i) => ({
157	        id: `a${i}`,
158	        kind: "step" as const,
159	        label: `repair ${i + 1}`,
160	        command: `${x.kind} · ${(x.files ?? []).join(", ")}`,
161	        ok: x.result === "passed",
162	        lines: [x.result ?? ""],
163	      })),
164	    },
165	    {
166	      icon: "prove" as const,
167	      title: "Proof in a clean container",
168	      body: "A second container clones the same commit, applies only the fix and reruns every step. The agent that wrote the fix can&apos;t touch it.",
169	      rows: stepRows(proof, "p"),
170	    },
171	  ].filter((i) => i.rows.length > 0);
172	  return (
173	    <section className="mx-auto max-w-7xl space-y-24 px-4 py-28 sm:px-6">
174	      {items.map((it, i) => (
175	        <div key={it.title} className="grid grid-cols-1 items-center gap-10 lg:grid-cols-2">
176	          <Reveal className={cn(i % 2 && "lg:order-2")}>
177	            <AnimIcon name={it.icon} className="size-9 text-accent-strong" />
178	            <h2 className="mt-5 text-4xl font-semibold tracking-tight sm:text-5xl">{it.title}</h2>
179	            <p className="mt-4 max-w-md text-lg text-muted-foreground">{it.body}</p>
180	          </Reveal>
181	          <Reveal delay={0.15} x={i % 2 ? -24 : 24}>
182	            <Terminal title={`${f.result.repo} · ${it.title.toLowerCase()}`} rows={it.rows} compact tailLines={4} />
183	          </Reveal>
184	        </div>
185	      ))}
186	    </section>
187	  );
188	}
189	
190	/* 4. Your projects --------------------------------------------------------- */
191	const COLLAPSED_REPOS = 12;
192	
193	/** "✓ 11 Runs · ◐ 3 Runs with gaps · …": the badges' own words and glyphs, one count per status. */
194	function statusCounts(runs: RunSummary[]) {
195	  const by = new Map<string, { n: number; m: ReturnType<typeof statusMeta> }>();
196	  for (const r of runs) {
197	    const m = statusMeta(r.status);
198	    const k = `${m.glyph} ${m.word}`;
199	    by.set(k, { n: (by.get(k)?.n ?? 0) + 1, m });
200	  }
201	  const rank = (w: string) => { const i = STATUS_ORDER.indexOf(w); return i < 0 ? STATUS_ORDER.length : i; };
202	  return [...by.entries()].sort(([, a], [, b]) => rank(a.m.word) - rank(b.m.word));
203	}
204	
205	function RepoCell({ r }: { r: RunSummary }) {
206	  const name = `${r.repo}${r.path ? `/${r.path}` : ""}`;
207	  return (
208	    <li>
209	      <Link
210	        to={`/runs/${r.id}`}
211	        title={name}
212	        className="flex h-full min-w-0 flex-col gap-1.5 rounded-md border border-border bg-panel px-3 py-2 hover:bg-muted"
213	      >
214	        <span className="block w-full truncate font-semibold">
215	          {r.repo}{r.path ? <span className="font-normal text-muted-foreground">/{r.path}</span> : null}
216	        </span>
217	        <span className="flex flex-wrap items-center justify-between gap-x-2 gap-y-1">
218	          <StatusBadge status={r.status} className="max-w-full rounded-xl" />
219	          <span className="font-mono text-sm tabular-nums text-muted-foreground">{fmtDur(r.duration_s)}</span>
220	        </span>
221	      </Link>
222	    </li>
223	  );
224	}
225	
226	function RepoGrid({ runs }: { runs: RunSummary[] }) {
227	  const [open, setOpen] = useState(false);
228	  const head = runs.slice(0, COLLAPSED_REPOS);
229	  const rest = runs.slice(COLLAPSED_REPOS);
230	  const grid = "grid grid-cols-1 gap-2 sm:grid-cols-2 lg:grid-cols-3";
231	  return (
232	    <div className="mt-8">
233	      <p className="mb-3 text-sm text-muted-foreground">
234	        {statusCounts(runs).map(([k, { n, m }], i, all) => (
235	          <Fragment key={k}>
236	            <span className="whitespace-nowrap">
237	              <span aria-hidden className={cn("font-mono", m.text)}>{m.glyph}</span> {n} {m.word}
238	              {i < all.length - 1 ? " ·" : ""}
239	            </span>{" "}
240	          </Fragment>
241	        ))}
242	      </p>
243	      <ul className={grid} role="list">
244	        {head.map((r) => <RepoCell key={r.id} r={r} />)}
245	      </ul>
246	      {rest.length > 0 && (
247	        <>
248	          <div id="repo-more" className="fold" data-open={open}>
249	            <div className="-mx-1 -mb-1 min-h-0 overflow-hidden px-1 pb-1">
250	              <ul className={cn(grid, "mt-2")} role="list">
251	                {rest.map((r) => <RepoCell key={r.id} r={r} />)}
252	              </ul>
253	            </div>
254	          </div>
255	          <button
256	            type="button"
257	            aria-expanded={open}
258	            aria-controls="repo-more"
259	            onClick={() => setOpen((o) => !o)}
260	            className="press mt-3 rounded-md border border-control px-3 py-1.5 text-sm font-semibold hover:bg-muted pointer-coarse:min-h-11 pointer-coarse:px-4"
261	          >
262	            {open ? "Show fewer" : `Show all ${runs.length} repositories`}
263	          </button>
264	        </>
265	      )}
266	    </div>
267	  );
268	}
269	
270	function Projects({ data }: { data: LandingData }) {
271	  const f = data.featured;
272	  if (!data.latest.length) return null;
273	  const a = f?.result.agent?.attempts?.[f.result.agent.attempts.length - 1];
274	  return (
275	    <section className="border-y border-border bg-panel/50">
276	      <div className="mx-auto grid max-w-7xl gap-10 px-4 py-24 sm:px-6 lg:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)]">
277	        <Reveal className="min-w-0">
278	          <Eyebrow>Checked repositories</Eyebrow>
279	          <h2 className="text-4xl font-semibold tracking-tight sm:text-5xl">One status per repository, in plain words.</h2>
280	          <RepoGrid runs={data.latest} />
281	          <p className="mt-3 text-sm text-muted-foreground">Latest run per repository, straight from the run records.</p>
282	        </Reveal>
283	        {a?.rationale && (
284	          <Reveal delay={0.15} className="min-w-0">
285	            <div className="flex items-center gap-4">
286	              <AgentOrb thinking={false} size={72} />
287	              <div>
288	                <h3 className="text-xl font-semibold">What the agent concluded</h3>
289	                <p className="text-sm text-muted-foreground">From {f?.result.repo}</p>
290	              </div>
291	            </div>
292	            <div className="mt-5 rounded-lg border border-border bg-panel p-4">
293	              <AIReasoning defaultOpen collapseWhenDone={false} duration={(f?.result.model_calls ?? []).reduce((s, c) => s + (c.duration_s ?? 0), 0) || undefined}>
294	                <p className="text-foreground">{a.rationale}</p>
295	                {a.confidence != null && <p className="mt-2 font-mono text-xs">confidence {a.confidence}</p>}
296	              </AIReasoning>
297	            </div>
298	          </Reveal>
299	        )}
300	      </div>
301	    </section>
302	  );
303	}
304	
305	/* 5. Open a run ------------------------------------------------------------ */
306	function OpenARun({ data }: { data: LandingData }) {
307	  // Everything here comes from the /api/runs summaries: no per-run fetch.
308	  // Fixes that only skipped tests are never shown here. Clean config fixes come first, then other fixes.
309	  const rank = (r: RunSummary) => (r.status === "runs" && r.fix_kind === "config" ? 0 : r.patch_preview ? 1 : 2);
310	  const cards = data.latest.filter(isShowable).sort((a, b) => rank(a) - rank(b)).slice(0, 3);
311	  if (!cards.length) return null;
312	  return (
313	    <section className="mx-auto max-w-7xl px-4 py-28 sm:px-6">
314	      <Reveal>
315	        <h2 className="max-w-3xl text-4xl font-semibold tracking-tight sm:text-6xl">Don&apos;t take our word for it. Open a run.</h2>
316	      </Reveal>
317	      <div className="mt-12 grid grid-cols-1 gap-6 lg:grid-cols-3">
318	        {cards.map((r, i) => {
319	          const file = r.patch_preview ? parsePatch(r.patch_preview)[0] : null;
320	          return (
321	            <Reveal key={r.id} delay={i * 0.1}>
322	              <Link to={`/runs/${r.id}`} className="group flex h-full flex-col rounded-xl border border-border bg-panel p-5 transition-colors hover:border-accent-strong">
323	                <StatusBadge status={r.status} className="self-start" />
324	                <h3 className="mt-4 break-words text-2xl font-semibold">{r.repo}</h3>
325	                <p className="mt-1 text-sm text-muted-foreground">
326	                  {fixLabel(r.fix_kind, r.needs_approval)} fix · {fmtDur(r.duration_s)} · {r.model_calls} model call{r.model_calls === 1 ? "" : "s"}
327	                </p>
328	                {file ? (
329	                  <pre className="mt-5 flex-1 overflow-hidden rounded-md border border-border bg-terminal p-3 font-mono text-xs leading-relaxed text-terminal-ink">
330	                    <span className="text-muted-foreground">{file.title}</span>
331	                    {file.lines.slice(0, 7).map((l, j) => (
332	                      <span key={j} className={cn("block whitespace-pre", l.kind === "added" && "bg-evidence text-on-evidence")}>
333	                        {l.kind === "added" ? "+" : l.kind === "removed" ? "-" : " "}{l.content}
334	                      </span>
335	                    ))}
336	                  </pre>
337	                ) : (
338	                  <p className="mt-5 flex-1 text-sm text-muted-foreground">
339	                    {r.fix_kind ? "Open the run to read the patch." : "No fix was recorded for this run."}
340	                  </p>
341	                )}
342	                <p className="mt-5 text-sm font-semibold underline-offset-4 group-hover:underline">Open the run <span aria-hidden>→</span></p>
343	              </Link>
344	            </Reveal>
345	          );
346	        })}
347	      </div>
348	    </section>
349	  );
350	}
351	
352	/* 6. The problem ----------------------------------------------------------- */
353	function Problem({ data }: { data: LandingData }) {
354	  if (!data.problems.length) return null;
355	  return (
356	    <section className="border-y border-border bg-panel/50">
357	      <div className="mx-auto max-w-7xl px-4 py-28 sm:px-6">
358	        <Reveal>
359	          <h2 className="max-w-4xl text-4xl font-semibold tracking-tight sm:text-6xl">Projects rot while you&apos;re not looking.</h2>
360	          <p className="mt-5 max-w-2xl text-lg text-muted-foreground">Nothing in the repository changed. These are the real causes Resurgo recorded.</p>
361	        </Reveal>
362	        <ol className={`mt-14 grid grid-cols-1 gap-px overflow-hidden rounded-xl border border-border bg-border ${data.problems.length >= 3 ? "lg:grid-cols-3" : data.problems.length === 2 ? "lg:grid-cols-2" : ""}`} role="list">
363	          {data.problems.map((p, i) => (
364	            <li key={p.key} className="bg-canvas">
365	              <Reveal delay={i * 0.12} className="flex h-full flex-col p-6">
366	                <span className="font-mono text-sm text-muted-foreground">0{i + 1}</span>
367	                <h3 className="mt-3 text-2xl font-semibold">{p.title}</h3>
368	                <p className="mt-3 text-muted-foreground">{p.body}</p>
369	                <blockquote className="mt-6 flex-1 whitespace-pre-wrap break-words border-l-2 border-evidence pl-4 font-mono text-xs leading-relaxed">
370	                  {p.evidence.length > 380 ? `${p.evidence.slice(0, 380)}…` : p.evidence}
371	                </blockquote>
372	                <Link to={`/runs/${p.runId}`} className="mt-5 text-sm text-muted-foreground underline underline-offset-4 hover:text-foreground">
373	                  Recorded in {p.source}
374	                </Link>
375	              </Reveal>
376	            </li>
377	          ))}
378	        </ol>
379	      </div>
380	    </section>
381	  );
382	}
383	
384	/** A median over fewer fixes than this carries its count in the label. */
385	const FEW = 5;
386	
387	function StatBlock({ g, lead, hold }: { g: StatGroup; lead: string | null; hold: boolean }) {
388	  const whole = (n: number) => String(Math.round(n));
389	  // A median over a handful of fixes says little: show how many it is taken over.
390	  const fewFixes = g.medianN < FEW ? ` (${g.medianN} ${g.medianN === 1 ? "fix" : "fixes"})` : "";
391	  const stats = [
392	    { k: "Repos checked", v: g.repos, format: whole },
393	    { k: "Verified in a clean container", v: g.verified, format: whole },
394	    ...(g.medianVerifiedS != null
395	      ? [{ k: `Median wall time of a verified fix${fewFixes}`, v: g.medianVerifiedS, format: fmtDur }]
396	      : []),
397	  ];
398	  return (
399	    <div className="min-w-0">
400	      <h3 className="mb-3 text-lg font-semibold">
401	        {lead ? <span className="mr-2 font-mono text-sm uppercase tracking-[0.12em] text-muted-foreground">{lead}</span> : null}
402	        {g.label}: {g.repos} repos
403	      </h3>
404	      <dl className="grid gap-px overflow-hidden rounded-xl border border-border bg-border sm:grid-cols-3">
405	        {stats.map((s) => (
406	          <div key={s.k} className="bg-canvas p-6">
407	            <dd className="font-mono text-4xl font-semibold tabular-nums tracking-tight sm:text-5xl">
408	              <NumberTicker value={s.v} format={s.format} hold={hold} />
409	            </dd>
410	            <dt className="mt-2 text-muted-foreground">{s.k}</dt>
411	          </div>
412	        ))}
413	      </dl>
414	      {g.skipped > 0 && (
415	        <p className="mt-3 text-sm text-muted-foreground">
416	          {g.skipped} {g.skipped === 1 ? "fix" : "fixes"} only skipped tests and {g.skipped === 1 ? "is" : "are"} not counted as verified.
417	        </p>
418	      )}
419	    </div>
420	  );
421	}
422	
423	/* 7. The solution: tabs ---------------------------------------------------- */
424	function Solution({ data }: { data: LandingData }) {
425	  const f = data.featured;
426	  if (!f) return null;
427	  const st = data.stats;
428	  // The beam in the tabs runs first; the numbers below count up only after it has finished.
429	  const [beamDone, setBeamDone] = useState(false);
430	  const compare = st.length > 1 && st.every((g) => g.set === "heldout");
431	  return (
432	    <section className="mx-auto max-w-7xl px-4 py-28 sm:px-6">
433	      <Reveal>
434	        <Eyebrow>How it works</Eyebrow>
435	        <h2 className="max-w-3xl text-4xl font-semibold tracking-tight sm:text-6xl">Check. Diagnose. Repair. Prove.</h2>
436	      </Reveal>
437	      <SolutionTabs detail={f} onBeamDone={() => setBeamDone(true)} />
438	
439	      {st.length > 0 && (
440	        <Reveal className="mt-16">
441	          {/* Two agent versions of the held-out set: the older is the before, the newest the after. Otherwise each block stands alone. */}
442	          <div className={cn("grid gap-8", st.length > 1 && "lg:grid-cols-2")}>
443	            {(compare ? [st[0], st[st.length - 1]] : st).map((g, i) => (
444	              <StatBlock key={g.key} g={g} lead={compare ? (i === 0 ? "Before" : "After") : null} hold={!beamDone} />
445	            ))}
446	          </div>
447	          <p className="mt-3 text-sm text-muted-foreground">
448	            Counted from the run records only. Each repo counts once, by its latest run in that set and agent version.
449	          </p>
450	        </Reveal>
451	      )}
452	    </section>
453	  );
454	}
