461	  const record = JSON.stringify(
462	    { run_id: r.run_id, repo: r.repo, sha: r.sha, type: r.type, agent_version: r.agent_version, needs_approval: r.needs_approval, fixed: r.fixed, result: r.result },
463	    null,
464	    2,
465	  );
466	  const proof = JSON.stringify(
467	    (r.verifier?.steps ?? []).map((s) => ({ name: s.name, exit_code: s.exit_code, duration_s: s.duration_s })),
468	    null,
469	    2,
