471	  const cards: { title: string; body: string; code: string }[] = [
472	    { title: "Reproduce it", body: "One command re-runs the check from a fresh clone.", code: commandFor(f.result) ?? "" },
473	    { title: "The run record", body: "Every run writes one JSON file. This is the real one, trimmed.", code: record },
474	    ...(f.fix_patch ? [{ title: "The patch", body: "The fix, as a plain unified diff you can read before it merges.", code: f.fix_patch.trim() }] : []),
475	    ...(proof !== "[]" ? [{ title: "The proof", body: "What the separate clean container ran, and how each step ended.", code: proof }] : []),
476	  ];
477	  return (
478	    <section className="border-y border-border bg-panel/50">
479	      <div className="mx-auto max-w-7xl px-4 py-28 sm:px-6">
480	        <Reveal>
481	          <h2 className="max-w-3xl text-4xl font-semibold tracking-tight sm:text-6xl">Everything it does is a file you can read.</h2>
482	          <p className="mt-4 text-muted-foreground">
483	            Agents can read it too: <a href="/index.md" className="font-semibold text-accent-strong underline underline-offset-4">the Agent view</a> (Markdown for AI agents) describes the API and how runs are proved.
484	          </p>
485	        </Reveal>
486	        <div className="mt-12 grid grid-cols-1 gap-6 md:grid-cols-2">
487	          {cards.map((c, i) => (
488	            <Reveal key={c.title} delay={(i % 2) * 0.1}>
489	              <div className="flex h-full flex-col rounded-xl border border-border bg-canvas p-5">
490	                <h3 className="text-xl font-semibold">{c.title}</h3>
491	                <p className="mt-1 text-muted-foreground">{c.body}</p>
492	                <pre className="mt-4 max-h-64 flex-1 overflow-auto rounded-md border border-border bg-terminal p-3 font-mono text-xs leading-relaxed text-terminal-ink" tabIndex={0}>
493	                  {c.code}
494	                </pre>
495	              </div>
496	            </Reveal>
497	          ))}
498	        </div>
499	      </div>
500	    </section>
501	  );
502	}
503	
504	/* 10. Toolchains ----------------------------------------------------------- */
505	const TOOLCHAINS: ImageName[] = ["node", "pnpm", "npm", "yarn", "foundry", "rust", "docker"];
506	const NAMES: Record<ImageName, string> = {
507	  neatlogsIcon: "neatlogs", node: "Node.js", pnpm: "pnpm", npm: "npm", yarn: "Yarn", foundry: "Foundry", rust: "Cargo (Rust)", docker: "Docker",
508	};
509	
