516	        {TOOLCHAINS.map((n) => (
517	          <li key={n} className={item}>
518	            <LogoImage name={n} size="44px" />
519	            {NAMES[n]}
520	          </li>
521	        ))}
522	        <li className={item}>
523	          <Logo name="github" brand size="44px" />
524	          GitHub
525	        </li>
526	      </ul>
527	    </section>
528	  );
529	}
