531	/* 11. Final CTA ------------------------------------------------------------ */
532	function Closing({ data }: { data: LandingData }) {
533	  const history = [...data.runs].filter((r) => r.status !== "checking").reverse();
534	  const tone = (s: string) => {
535	    const m = statusMeta(s);
536	    return m.text === "text-runs"
537	      ? "bg-runs text-canvas"
538	      : m.text === "text-broken"
539	        ? "bg-broken text-canvas"
540	        : m.text === "text-approval"
541	          ? "bg-approval text-canvas"
542	          : "bg-gaps text-canvas";
543	  };
544	  const steps = ["Install the app", "Pick the repos", "Resurgo checks each from a fresh clone", "A pull request for each verified fix"];
545	  return (
546	    <section className="mx-auto max-w-7xl px-4 py-28 sm:px-6">
547	      <Reveal>
548	        <h2 className="max-w-4xl text-5xl font-semibold leading-[1.02] tracking-tight sm:text-7xl">Install it. Pick the repos.</h2>
549	        <p className="mt-6 max-w-2xl text-lg text-muted-foreground">
550	          Install the Resurgo Agent GitHub App on the repos you pick. It opens a pull request only for a fix that passed in a clean container. A change to your code waits for your approval.
551	        </p>
552	      </Reveal>
553	
554	      {history.length > 0 && (
555	        <Reveal className="mt-14">
556	          <p className="mb-3 text-sm text-muted-foreground">
557	            Every run so far, oldest to newest ({history.length}). Open any bar.
558	          </p>
559	          <ol className="flex h-20 gap-0.5" role="list">
560	            {history.map((r) => (
561	              <li key={r.id} className="min-w-0 flex-1">
562	                <Link
563	                  to={`/runs/${r.id}`}
564	                  title={`${r.repo} · ${statusMeta(r.status).word}`}
565	                  className={cn("flex h-full min-w-0 items-start justify-center overflow-hidden rounded-sm pt-1.5 text-sm font-bold hover:opacity-80", tone(r.status))}
566	                >
