/* 3. Three steps, as story rows -------------------------------------------- */
function Steps({ data }: { data: LandingData }) {
  const f = data.featured;
  if (!f) return null;
  const a = f.result.agent;
  const clone = (a?.steps ?? []).filter((s) => s.name === "clone" || s.name === "detect").slice(0, 2);
  const attempts = a?.attempts ?? [];
  const proof = f.result.verifier?.steps ?? [];
  const items: { icon: IconName; title: string; body: string; rows: TermRow[] }[] = [
    {
      icon: "check" as const,
      title: "A fresh clone, every time",
      body: "No cached node_modules, no warm machine. If it only works on your laptop, this is where it stops working.",
      rows: stepRows(clone, "c"),
    },
    {
      icon: "repair" as const,
      title: "The least invasive fix first",
      body: "Version pins and config before anything else. Source code is only ever proposed, and waits for your approval.",
      rows: attempts.map((x, i) => ({
        id: `a${i}`,
        kind: "step" as const,
        label: `repair ${i + 1}`,
        command: `${x.kind} · ${(x.files ?? []).join(", ")}`,
        ok: x.result === "passed",
        lines: [x.result ?? ""],
      })),
    },
    {
      icon: "prove" as const,
      title: "Proof in a clean container",
      body: "A second container clones the same commit, applies only the fix and reruns every step. The agent that wrote the fix can&apos;t touch it.",
      rows: stepRows(proof, "p"),
    },
  ].filter((i) => i.rows.length > 0);
  return (
    <section className="mx-auto max-w-7xl space-y-24 px-4 py-28 sm:px-6">
      {items.map((it, i) => (
        <div key={it.title} className="grid grid-cols-1 items-center gap-10 lg:grid-cols-2">
          <Reveal className={cn(i % 2 && "lg:order-2")}>
            <AnimIcon name={it.icon} className="size-9 text-accent-strong" />
            <h2 className="mt-5 text-4xl font-semibold tracking-tight sm:text-5xl">{it.title}</h2>
            <p className="mt-4 max-w-md text-lg text-muted-foreground">{it.body}</p>
          </Reveal>
          <Reveal delay={0.15} x={i % 2 ? -24 : 24}>
            <Terminal title={`${f.result.repo} · ${it.title.toLowerCase()}`} rows={it.rows} compact tailLines={4} />
          </Reveal>
        </div>
      ))}
    </section>
  );
}

/* 4. Your projects --------------------------------------------------------- */
const COLLAPSED_REPOS = 12;

/** "✓ 11 Runs · ◐ 3 Runs with gaps · …": the badges' own words and glyphs, one count per status. */
function statusCounts(runs: RunSummary[]) {
  const by = new Map<string, { n: number; m: ReturnType<typeof statusMeta> }>();
  for (const r of runs) {
    const m = statusMeta(r.status);
    const k = `${m.glyph} ${m.word}`;
    by.set(k, { n: (by.get(k)?.n ?? 0) + 1, m });
  }
  const rank = (w: string) => { const i = STATUS_ORDER.indexOf(w); return i < 0 ? STATUS_ORDER.length : i; };
  return [...by.entries()].sort(([, a], [, b]) => rank(a.m.word) - rank(b.m.word));
}

function RepoCell({ r }: { r: RunSummary }) {
  const name = `${r.repo}${r.path ? `/${r.path}` : ""}`;
  return (
    <li>
      <Link
        to={`/runs/${r.id}`}
        title={name}
        className="flex h-full min-w-0 flex-col gap-1.5 rounded-md border border-border bg-panel px-3 py-2 hover:bg-muted"
      >
        <span className="block w-full truncate font-semibold">
          {r.repo}{r.path ? <span className="font-normal text-muted-foreground">/{r.path}</span> : null}
        </span>
        <span className="flex flex-wrap items-center justify-between gap-x-2 gap-y-1">
          <StatusBadge status={r.status} className="max-w-full rounded-xl" />
          <span className="font-mono text-sm tabular-nums text-muted-foreground">{fmtDur(r.duration_s)}</span>
        </span>
      </Link>
    </li>
  );
}

function RepoGrid({ runs }: { runs: RunSummary[] }) {
  const [open, setOpen] = useState(false);
  const head = runs.slice(0, COLLAPSED_REPOS);
  const rest = runs.slice(COLLAPSED_REPOS);
  const grid = "grid grid-cols-1 gap-2 sm:grid-cols-2 lg:grid-cols-3";
  return (
    <div className="mt-8">
      <p className="mb-3 text-sm text-muted-foreground">
        {statusCounts(runs).map(([k, { n, m }], i, all) => (
          <Fragment key={k}>
            <span className="whitespace-nowrap">
              <span aria-hidden className={cn("font-mono", m.text)}>{m.glyph}</span> {n} {m.word}
              {i < all.length - 1 ? " ·" : ""}
            </span>{" "}
          </Fragment>
        ))}
      </p>
      <ul className={grid} role="list">
        {head.map((r) => <RepoCell key={r.id} r={r} />)}
      </ul>
      {rest.length > 0 && (
        <>
          <div id="repo-more" className="fold" data-open={open}>
            <div className="-mx-1 -mb-1 min-h-0 overflow-hidden px-1 pb-1">
              <ul className={cn(grid, "mt-2")} role="list">
                {rest.map((r) => <RepoCell key={r.id} r={r} />)}
              </ul>
            </div>
          </div>
          <button
            type="button"
            aria-expanded={open}
            aria-controls="repo-more"
            onClick={() => setOpen((o) => !o)}
            className="press mt-3 rounded-md border border-control px-3 py-1.5 text-sm font-semibold hover:bg-muted pointer-coarse:min-h-11 pointer-coarse:px-4"
          >
            {open ? "Show fewer" : `Show all ${runs.length} repositories`}
          </button>
        </>
      )}
    </div>
  );
}

function Projects({ data }: { data: LandingData }) {
  const f = data.featured;
  if (!data.latest.length) return null;
