        </Reveal>
        <ol className={`mt-14 grid grid-cols-1 gap-px overflow-hidden rounded-xl border border-border bg-border ${data.problems.length >= 3 ? "lg:grid-cols-3" : data.problems.length === 2 ? "lg:grid-cols-2" : ""}`} role="list">
