export function Logo({
  name,
  size = "1em",
  brand = false,
  decorative = false,
  className,
}: {
  name: MaskName;
  size?: string;
  brand?: boolean;
  decorative?: boolean;
  className?: string;
}) {
  const theme = useTheme();
