import { useMemo } from "react";
import { useRun, useRuns, type RunDetail, type RunSummary } from "@/lib/api";
import { latestPerRepo, pickFeatured, runTag } from "@/lib/run";

export type Problem = {
  key: string;
  title: string;
  body: string;
  /** What the run record literally says. */
  evidence: string;
  source: string;
  runId: string;
};

export type LandingData = {
  loading: boolean;
  error: string | null;
  runs: RunSummary[];
  /** The featured run's full record: the only per-run fetch the landing page makes. */
  featured: RunDetail | null;
  featuredSummary: RunSummary | null;
  /** The oldest recorded run of the featured repo: where it started out. */
  before: RunSummary | null;
  latest: RunSummary[];
  problems: Problem[];
  /** One block per evaluation set and agent version, counted from the records only. */
  stats: StatGroup[];
};

export type StatGroup = {
  key: string;
  /** "Held-out set, agent v1" */
  label: string;
  set: string | null;
  version: string | null;
  repos: number;
  verified: number;
  /** Repos whose fix only skipped tests: never counted as verified. */
  skipped: number;
  medianVerifiedS: number | null;
  /** How many fixes the median was taken over. */
  medianN: number;
};

const median = (xs: number[]) => {
  if (!xs.length) return null;
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

const PROBLEM_COPY: Record<string, { title: string; body: string }> = {
  toolchain: {
    title: "The toolchain moved",
    body: "A package manager tightened its defaults, and a lockfile that installed last spring now refuses to install.",
  },
  runtime: {
    title: "The runtime moved",
    body: "A native module built against an older Node never learned the newer one, so the install itself fails.",
  },
  clock: {
    title: "The build never finishes",
    body: "Some projects grew past the point where a clean build completes inside a sensible time cap, and nobody noticed because nobody builds from scratch.",
  },
};

/** First run (newest first) that evidences each cause. The server did the matching. */
function findProblems(runs: RunSummary[]): Problem[] {
  return (["toolchain", "runtime", "clock"] as const).flatMap((key) => {
    for (const r of runs) {
      const p = r.problems?.find((x) => x.key === key);
      if (p) return [{ key, ...PROBLEM_COPY[key], evidence: p.evidence, source: r.repo ?? "", runId: r.id }];
    }
    return [];
  });
}

/**
 * Latest run per repo within each (set, agent version). The held-out groups win; with none recorded,
 * whatever groups exist are shown under their own labels.
 */
function statGroups(real: RunSummary[]): StatGroup[] {
  const by = new Map<string, RunSummary[]>();
  for (const r of real) {
    const key = `${r.set ?? ""}|${r.agent_version ?? ""}`;
    by.set(key, [...(by.get(key) ?? []), r]);
  }
  const groups = [...by.entries()].map(([key, rs]): StatGroup => {
    const latest = latestPerRepo(rs);
    const skipped = latest.filter((r) => r.status === "fix_skipped_tests" || r.weakens_tests);
    // `verified` may be absent from the list; the status already says whether the clean container passed.
    const verified = latest.filter(
      (r) => !skipped.includes(r) && (r.verified ?? (r.status === "runs" || r.status === "runs_with_gaps" || r.status === "fix_awaiting_approval")),
    );
    const times = verified.filter((r) => r.fix_kind && r.duration_s != null).map((r) => r.duration_s as number);
    return {
      key,
      label: runTag(rs[0]) ?? "Earlier runs, set not recorded",
      set: rs[0].set ?? null,
      version: rs[0].agent_version ?? null,
      repos: latest.length,
      verified: verified.length,
      skipped: skipped.length,
      medianVerifiedS: median(times),
      medianN: times.length,
    };
  });
  const heldout = groups.filter((g) => g.set === "heldout");
  return (heldout.length ? heldout : groups).sort((a, b) =>
    (a.version ?? "").localeCompare(b.version ?? "", "en", { numeric: true }),
  );
}

export function useLandingData(): LandingData {
  const { data: runs, loading, error } = useRuns();
  const list = useMemo(() => runs ?? [], [runs]);
  const featuredSummary = useMemo(() => pickFeatured(list), [list]);
  const { data: featured } = useRun(featuredSummary?.id ?? null);

  return useMemo(() => {
    const f = featuredSummary;
    const before = f
      ? [...list].reverse().find((r) => r.repo === f.repo && r.path === f.path && r.id !== f.id && r.status !== "checking") ?? null
      : null;
    const real = list.filter((r) => r.status !== "checking");
    return {
      loading,
      error,
      runs: list,
      featured,
      featuredSummary: f,
      before,
      latest: latestPerRepo(list),
      problems: findProblems(real),
      stats: statGroups(real),
    };
  }, [list, featured, featuredSummary, loading, error]);
}

import { cn } from "@/lib/utils";
import { useTheme } from "@/lib/theme";

/**
 * Original logos from /logos (sources in web/public/logos/SOURCES.md).
 *
 * `Logo` draws a one-colour file as a CSS mask. With `brand` it takes the colour the brand itself uses
 * on that background; without, it follows the text colour (the mark inside the Install buttons).
 * `LogoImage` draws a full-colour file as it is, so its own colours show in both themes.
 */
const MASKS = {
  neatlogs: { name: "neatlogs", file: "neatlogs-wordmark.webp", ratio: 1100 / 243, dark: "#F5F5F2" }, // light: the page's ink (text-foreground)
  entire: { name: "Entire", file: "entire.svg", ratio: 959.94 / 236.81, light: "#1C1917", dark: "#FFFFFF" },
  cfo: { name: "cfo.ai", file: "cfo.svg", ratio: 1 },
  github: { name: "GitHub", file: "github.svg", ratio: 1, light: "#1F2328", dark: "#FFFFFF" },
  bun: { name: "Bun", file: "bun.svg", ratio: 1 },
} as const;

const IMAGES = {
  // A dark rounded square: it gets a 1px edge so it doesn't melt into the dark canvas.
  neatlogsIcon: { name: "neatlogs app icon", file: "neatlogs-icon.png", edge: true },
  node: { name: "Node.js", file: "node-js-icon.svg" },
  pnpm: { name: "pnpm", file: "pnpm-frame.svg" },
  npm: { name: "npm", file: "npm-square.svg" },
  yarn: { name: "Yarn", file: "yarn-kitten-circle.svg" },
  foundry: { name: "Foundry", file: "foundry-logo.png" },
  // Black artwork: shown white on the dark canvas, as Checkly does for black logos.
  // The artwork has built-in padding, so it reads small beside its neighbours; scaled up in CSS only.
  rust: { name: "Cargo (Rust)", file: "rust-logo-blk.svg", invertOnDark: true, optical: 1.2 },
  docker: { name: "Docker", file: "docker-mark-blue.svg" },
} as const;

export type MaskName = keyof typeof MASKS;
export type ImageName = keyof typeof IMAGES;

/**
 * `size` is the logo's height as a CSS length ("32px", or "1.25em" to sit in text). The logo is an
 * image named for its product; `decorative` hides it where visible text next to it already names it.
 */
export function Logo({
  name,
  size = "1em",
  brand = false,
  decorative = false,
  className,
}: {
  name: MaskName;
  size?: string;
  brand?: boolean;
  decorative?: boolean;
  className?: string;
}) {
  const theme = useTheme();
  const l: { name: string; file: string; ratio: number; light?: string; dark?: string } = MASKS[name];
  const url = `url(/logos/${l.file})`;
  const a11y = decorative ? { "aria-hidden": true as const } : { role: "img" as const, "aria-label": l.name };
  return (
    <span
      {...a11y}
      title={l.name}
      data-logo={name}
      className={cn("inline-block shrink-0", className)}
      style={{
        height: size,
        width: `calc(${size} * ${l.ratio})`,
        backgroundColor: (brand && (theme === "dark" ? l.dark : l.light)) || "currentColor",
        WebkitMaskImage: url,
        maskImage: url,
        WebkitMaskRepeat: "no-repeat",
        maskRepeat: "no-repeat",
        WebkitMaskPosition: "center",
        maskPosition: "center",
        WebkitMaskSize: "contain",
        maskSize: "contain",
      }}
    />
  );
}

export function LogoImage({ name, size, className }: { name: ImageName; size: string; className?: string }) {
  const theme = useTheme();
  const l: { name: string; file: string; invertOnDark?: boolean; edge?: boolean; optical?: number } = IMAGES[name];
  return (
    <img
      src={`/logos/${l.file}`}
      alt={l.name}
      title={l.name}
      data-logo={name}
      draggable={false}
      className={cn("block w-auto max-w-none shrink-0", className)}
      style={{
        height: size,
        filter: l.invertOnDark && theme === "dark" ? "invert(1)" : undefined,
        scale: l.optical,
        outline: l.edge ? `1px solid ${theme === "dark" ? "oklch(1 0 0 / 0.1)" : "oklch(0 0 0 / 0.1)"}` : undefined,
        outlineOffset: l.edge ? "-1px" : undefined,
      }}
    />
  );
}

